const CAPTIONS = [
  "CarCard / Size: Full / State: Default",
  "CarCard / Size: Full / State: Hover",
  "CarCard / Size: Full / State: Pressed",
  "CarCard / Size: Full / State: Focus",
  "CarCard / Size: Compact / State: Default",
  "CarCard / Size: Compact / State: Hover",
  "CarCard / Size: Compact / State: Pressed",
  "CarCard / Size: Compact / State: Focus"
];

export default {
  title: "Cards and rows/CarCard",
  tags: ['autodocs'],
  parameters: {
    docs: { description: { component: "Generated from the Figma component set `CarCard` (page: Page 2).\n\nRoot element `<article>`, base class `.oc-carcard`.\n8 variants, axes: Size × State.\n\nValues come from the Figma bindings; nothing here is hand-tuned. Full property table in the\ncomponent's [README](../../components/CarCard/README.md)." } },
  },
  argTypes: {
    "Size": {
      description: "Figma variant property \"Size\"",
      control: { type: 'inline-radio' },
      options: ["Full","Compact"],
    },
    "State": {
      description: "Figma variant property \"State\"",
      control: { type: 'inline-radio' },
      options: ["Default","Hover","Pressed","Focus"],
    },
  },
  args: {
    "Size": "Full",
    "State": "Default",
  },
};

// Each combination is a real Figma variant, so the control picks markup rather than
// toggling a class - a variant can differ in structure, not just in styling.
export const Playground = {
  render: (args) => {
    const key = ["Size","State"].map((a) => args[a]).join('|');
    return (
      VARIANTS[key] ||
      '<p style="color: var(--color-text-tertiary)">This combination does not exist in Figma.</p>'
    );
  },
};

export const AllVariants = {
  name: "All variants",
  parameters: { controls: { disable: true } },
  render: () => {
    const keys = Object.keys(VARIANTS);
    return `<div style="display:flex;flex-wrap:wrap;gap:20px;align-items:flex-start">${keys
      .map(
        (k, i) =>
          `<figure style="margin:0;display:flex;flex-direction:column;gap:8px;align-items:flex-start">${VARIANTS[k]}<figcaption style="font:12px ui-monospace,monospace;color:var(--color-text-tertiary)">${CAPTIONS[i]}</figcaption></figure>`
      )
      .join('')}</div>`;
  },
};

